# --------------------------------------------------------------- helpers ---
function Get-Root([string]$Key) {
    if ($Key -eq 'app') { return $BackendPath } else { return $MobilePath }
}

function Read-Norm([string]$Path) {
    # returns @{ Text = <LF-normalised text>; Crlf = <bool> }
    $raw = [System.IO.File]::ReadAllText($Path, $Utf8NoBom)
    if ($raw.Length -gt 0 -and $raw[0] -eq [char]0xFEFF) { $raw = $raw.Substring(1) }
    return @{ Text = $raw.Replace("`r`n", "`n"); Crlf = $raw.Contains("`r`n") }
}

function Count-Occurrences([string]$Text, [string]$Needle) {
    $n = 0; $i = 0
    while (($i = $Text.IndexOf($Needle, $i, [System.StringComparison]::Ordinal)) -ge 0) { $n++; $i += $Needle.Length }
    return $n
}

function Normalize([string]$s) { return $s.Replace("`r`n", "`n") }

# ------------------------------------------------------------- pre-flight ---
if (-not (Test-Path (Join-Path $BackendPath 'manage.py')))  { throw "BackendPath is not the cavallo-app repo (manage.py not found): $BackendPath" }
if (-not (Test-Path (Join-Path $MobilePath  'pubspec.yaml'))) { throw "MobilePath is not the cavallo-mobile repo (pubspec.yaml not found): $MobilePath" }

# Plan everything in memory first; write only if every step is OK.
$Plan = @()     # @{ Path; Text; Crlf; Note }
$Notes = @()

foreach ($e in $Edits) {
    $path = Join-Path (Get-Root $e.Root) $e.Rel
    if (-not (Test-Path $path)) { throw "Missing file: $path" }
    $f = Read-Norm $path
    $text = $f.Text
    $changed = $false
    $i = 0
    foreach ($h in $e.Hunks) {
        $i++
        $old = Normalize $h.Old
        $new = Normalize $h.New
        if ($text.Contains($new)) { continue }                       # already applied
        $c = Count-Occurrences $text $old
        if ($c -ne 1) {
            throw "Cannot apply edit #$i to $($e.Rel): expected 1 matching block, found $c. The file differs from GitHub main - send me its current content and I will adapt the script. NOTHING was changed."
        }
        $idx = $text.IndexOf($old, [System.StringComparison]::Ordinal)
        $text = $text.Substring(0, $idx) + $new + $text.Substring($idx + $old.Length)
        $changed = $true
    }
    if ($changed) { $Plan += @{ Path = $path; Text = $text; Crlf = $f.Crlf } }
    else { $Notes += "already applied : $($e.Rel)" }
}

foreach ($w in $Wholes) {
    $path = Join-Path (Get-Root $w.Root) $w.Rel
    if (-not (Test-Path $path)) { throw "Missing file: $path" }
    $f = Read-Norm $path
    $target = Normalize $w.Content
    if ($f.Text -eq $target) { $Notes += "already applied : $($w.Rel)"; continue }
    $sha = [System.BitConverter]::ToString([System.Security.Cryptography.SHA256]::Create().ComputeHash($Utf8NoBom.GetBytes($f.Text))).Replace('-', '').ToLower()
    if ($sha -ne $w.OrigSha) { $Notes += "WARNING        : $($w.Rel) differs from GitHub main (local edits?). It will be replaced; your version is kept as .bak_newchat" }
    $Plan += @{ Path = $path; Text = $target; Crlf = $f.Crlf }
}

foreach ($n in $News) {
    $path = Join-Path (Get-Root $n.Root) $n.Rel
    $target = Normalize $n.Content
    if (Test-Path $path) {
        $f = Read-Norm $path
        if ($f.Text -eq $target) { $Notes += "already present : $($n.Rel)"; continue }
        $Notes += "WARNING        : $($n.Rel) already exists with different content; it will be replaced (backup kept)"
    }
    $Plan += @{ Path = $path; Text = $target; Crlf = ($n.Eol -eq 'CRLF') }
}

# ------------------------------------------------------------------ write ---
foreach ($p in $Plan) {
    $dir = Split-Path $p.Path -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir | Out-Null }
    if (Test-Path $p.Path) {
        $bak = "$($p.Path).bak_newchat"
        if (-not (Test-Path $bak)) { Copy-Item $p.Path $bak }
    }
    $out = $p.Text
    if ($p.Crlf) { $out = $out.Replace("`n", "`r`n") }
    [System.IO.File]::WriteAllText($p.Path, $out, $Utf8NoBom)
    Write-Host ("updated        : " + $p.Path) -ForegroundColor Green
}
foreach ($n in $Notes) { Write-Host $n -ForegroundColor Yellow }
if ($Plan.Count -eq 0) { Write-Host 'Nothing to do - everything was already applied.' -ForegroundColor Cyan }

# ----------------------------------------------------------------- checks ---
if ($RunChecks) {
    Write-Host "`n== Flutter ==" -ForegroundColor Cyan
    Push-Location $MobilePath
    try {
        flutter analyze lib/features/chat test/features/chat
        flutter test test/features/chat
    } finally { Pop-Location }

    Write-Host "`n== Backend ==" -ForegroundColor Cyan
    Push-Location $BackendPath
    try { python -m pytest chat/test_followed_businesses.py chat/test_start_by_business.py -q }
    finally { Pop-Location }
}

Write-Host @"

Done. Next steps:
  1) Backend (no migration needed). Restart the server, e.g.  docker compose restart web
     Tests:  python -m pytest chat/test_followed_businesses.py -q
  2) Mobile:  flutter analyze ; flutter test test/features/chat ; then run the app (generated l10n files were edited by hand to match gen-l10n; `flutter gen-l10n` should produce no diff).
  3) In the app: Messages -> "New chat" -> pick a business you follow.
"@